private fun selectedCases(): List<SmokeCase> {
    val filter = System.getenv("SCALAR_SMOKE_FILTER")
    val needles = filter?.split(",")?.map { it.trim() }?.filter { it.isNotEmpty() }.orEmpty()
    if (needles.isEmpty()) return cases
    return cases.filter { testCase ->
        needles.any { needle ->
            testCase.operation.contains(needle) || testCase.path.contains(needle)
        }
    }
}

private fun runCase(testCase: SmokeCase): SmokeResult {
    val startedAt = System.nanoTime()
    return try {
        testCase.run()
        SmokeResult(
            operation = testCase.operation,
            method = testCase.method,
            path = testCase.path,
            label = testCase.label,
            status = "passed",
            durationMs = (System.nanoTime() - startedAt) / 1_000_000,
        )
    } catch (error: Throwable) {
        SmokeResult(
            operation = testCase.operation,
            method = testCase.method,
            path = testCase.path,
            label = testCase.label,
            status = "failed",
            durationMs = (System.nanoTime() - startedAt) / 1_000_000,
            error = error.stackTraceToString(),
        )
    }
}

private fun writeReport(results: List<SmokeResult>, failed: Int) {
    val reportPath = System.getenv("SCALAR_SMOKE_REPORT")
    val json = buildString {
        append("{\"total\":").append(results.size)
        append(",\"failed\":").append(failed)
        append(",\"results\":[")
        results.forEachIndexed { index, result ->
            if (index > 0) append(",")
            append("{\"operation\":\"").append(escapeJson(result.operation)).append("\",")
            append("\"method\":\"").append(escapeJson(result.method)).append("\",")
            append("\"path\":\"").append(escapeJson(result.path)).append("\",")
            result.label?.let { append("\"label\":\"").append(escapeJson(it)).append("\",") }
            append("\"status\":\"").append(escapeJson(result.status)).append("\",")
            append("\"durationMs\":").append(result.durationMs)
            result.error?.let { append(",\"error\":\"").append(escapeJson(it)).append("\"") }
            append("}")
        }
        append("]}")
    }
    if (!reportPath.isNullOrBlank()) Files.writeString(Path.of(reportPath), json)
}

private fun escapeJson(value: String): String = buildString {
    for (char in value) {
        when (char) {
            '\\' -> append("\\\\")
            '"' -> append("\\\"")
            '\n' -> append("\\n")
            '\r' -> append("\\r")
            '\t' -> append("\\t")
            else -> append(char)
        }
    }
}

class SmokeTest {
    @Test
    fun smoke() {
        val selected = selectedCases()
        val results = selected.map(::runCase)
        val failed = results.count { it.status == "failed" }
        writeReport(results, failed)

        for (result in results) {
            val suffix = result.label?.let { " [" + it + "]" }.orEmpty()
            if (result.status == "passed") {
                println(
                    "PASS ${result.operation}$suffix (${result.method} ${result.path}) ${result.durationMs}ms"
                )
            } else {
                System.err.println(
                    "FAIL ${result.operation}$suffix (${result.method} ${result.path})\n${result.error.orEmpty()}"
                )
            }
        }

        if (failed > 0 || results.isEmpty()) {
            throw AssertionError("${results.size - failed}/${results.size} samples passed")
        }
    }
}
